(function(root){
'use strict';
function mount(panel,options={}){
 const model=root.PLOfficialModel.create(root.PLOfficialSample),r=model.reference('completed_match_reference'),esc=root.MatchWorkspace.esc;
 let rendered=false,section='events',active=false;
 const node=id=>panel.querySelector('#pl-o-'+id),team=id=>id==='brentford'?'Brentford':'Chelsea',name=id=>model.player(id)?.name||'Unknown';
 const source=e=>{const s=model.source(e.source);return `<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.publisher)} ↗</a><small>${esc(e.locator)}</small>`;};
 const proof=(items,label='Sources',note='')=>`<details class="official-proof"><summary>${label}</summary>${items.filter(Boolean).map(source).join('')}${note?'<p>'+esc(note)+'</p>':''}</details>`;
 const time=t=>esc(t.printed)+'′';
 function events(){return `<p class="official-section-note">Reported minutes · 3 goals, 9 substitutions, 2 yellow cards.</p><ol class="official-events">${r.events.map(e=>{
  const title=name(e.kind==='substitution'?e.on:e.player),subtitle=e.kind==='goal'?'Goal':e.kind==='substitution'?'on · '+name(e.off)+' off':'Yellow card';
  let detail=e.kind==='goal'?`${esc(e.finish.body_part==='head'?'Header':e.finish.body_part==='right_foot'?'Right foot':e.finish.body_part)} · ${esc(e.finish.source_location_description)}${e.finish.source_sequence?' · '+esc(e.finish.source_sequence):''}. ${e.assist.player?'Assist: '+esc(name(e.assist.player))+'.':'No formal assist explicitly credited in the reviewed record.'}`:e.kind==='yellow_card'?`Reason as reported: ${esc(e.reason)}.`:'';
  return `<li class="official-event ${e.kind}"><strong class="official-minute">${time(e.time)}</strong><div><small>${team(e.team)}</small><h3>${esc(title)} <span>${esc(subtitle)}</span></h3>${detail?'<p>'+detail+'</p>':''}${e.id==='goal-1'?'<button id="pl-o-explore" class="official-explore">Explore video passage ↗</button><p class="official-link-note">Estimated positions · finish/contact and exact goal time unverified.</p>':''}${proof([e.evidence,e.kind==='goal'?e.assist.evidence:null,...(e.disagreements||[]).map(d=>d.evidence)],'Sources',e.id==='goal-1'?'Related source clip 01:01:48–01:01:59; captured clock starts about 60:22 in the wide action and sampled scoreboard remains 0–0. The reported 61 minute and media seconds are separate. Finish/contact and exact goal time have not been verified or reconstructed. No exact event alignment or named marker join.':e.id==='goal-2'?'Premier League reports 83 minutes. Brentford’s report prints 80; the disagreement is retained.':'')}</div></li>`;
 }).join('')}</ol>`;}
 function lineups(){return `<p class="official-section-note">Official match roster · 11 starters and 9 bench players per team. Named roster, separate from anonymous pitch markers.</p><div class="official-team-grid">${['brentford','chelsea'].map(id=>{const f=r.formations.find(f=>f.team===id);return `<section class="official-team ${id}"><div class="official-team-heading"><h3>${team(id)}</h3><strong>${esc(f.value)}</strong></div><p>Premier League formation label</p>${proof([f.evidence,...f.disagreements.map(d=>d.evidence)],'Formation sources & disagreement','Club reports list '+[...new Set(f.disagreements.map(d=>d.value))].join(' / ')+'. Formation labels are not measured positions; individual roles remain unknown.')}${['starter','bench'].map(status=>`<h4>${status==='starter'?'Starting XI':'Bench'}</h4><ol class="official-roster">${model.team(id).filter(p=>p.status===status).map(p=>`<li><span class="official-shirt">${p.shirt}</span><div><strong>${esc(p.name)}${p.captainEvidence?' <span class="official-captain" title="Captain">C</span>':''}</strong>${proof([p.lineupEvidence,p.nameEvidence,p.captainEvidence])}</div></li>`).join('')}</ol>`).join('')}</section>`;}).join('')}</div>`;}
 function stats(){return `<p class="official-section-note"><strong>Completed-match summary</strong> · These are not statistics at the video cursor. Eleven selected official metrics.</p><table class="official-stats"><thead><tr><th scope="col">Brentford</th><th scope="col">Statistic</th><th scope="col">Chelsea</th></tr></thead><tbody>${r.stats.map(s=>`<tr><td>${s.values.brentford}${s.unit==='percent'?'%':''}</td><th scope="row">${esc(s.source_label)}${proof([s.evidence])}</th><td>${s.values.chelsea}${s.unit==='percent'?'%':''}</td></tr>`).join('')}</tbody></table>`;}
 function info(){return `<div class="official-info-grid"><section><h3>At the ground</h3><dl><dt>Stadium</dt><dd>${esc(r.summary.venue.value)}${proof([r.summary.venue.evidence])}</dd><dt>Attendance</dt><dd>${r.summary.attendance.value.toLocaleString('en-GB')}${proof([r.summary.attendance.evidence])}</dd><dt>Scheduled kickoff</dt><dd>${esc(r.summary.scheduledKickoff.local)} ${esc(r.summary.scheduledKickoff.zone)}${proof([r.summary.scheduledKickoff.evidence])}<small>Preview schedule; actual UTC kickoff not established by this import. The Info page display can use the viewer’s timezone.</small></dd></dl></section><section><h3>Match officials</h3><dl>${r.summary.officials.map(o=>`<dt>${esc(o.role)}</dt><dd>${esc(o.name)}${proof([o.evidence])}</dd>`).join('')}</dl><p class="official-section-note">The club report prints “Andrew Madley”; the league record prints “Andy Madley”. The source name variant is retained.</p></section></div>`;}
 function show(value){if(!['events','lineups','stats','info'].includes(value))return;section=value;for(const id of ['events','lineups','stats','info'])node(id).setAttribute('aria-pressed',String(id===section));node('content').innerHTML=({events,lineups,stats,info})[section]();}
 function render(){if(rendered)return;rendered=true;panel.innerHTML=`<section class="official-record" aria-label="Completed official match record"><div class="official-heading"><div><span class="eyebrow">COMPLETED-MATCH REFERENCE</span><h2>${esc(r.fixture.home)} <strong>${r.fixture.result.value[0]} <span>–</span> ${r.fixture.result.value[1]}</strong> ${esc(r.fixture.away)}</h2><p>${esc(new Date(r.fixture.date.value+'T00:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}))} · ${esc(r.fixture.competition.value)} ${esc(r.fixture.season.value)}</p></div><button id="pl-o-return" class="text-button">← Back to the pitch</button></div><p class="official-scope">Official match facts, separate from the paused video. This record includes later events and final statistics.</p>${proof([r.fixture.date.evidence,r.fixture.season.evidence,r.fixture.competition.evidence,r.fixture.result.evidence],'Fixture & result sources')}<div class="official-tabs" role="group" aria-label="Official record section">${[['events','Events'],['lineups','Lineups'],['stats','Stats'],['info','Match info']].map(([id,label])=>`<button id="pl-o-${id}" aria-pressed="${id===section}">${label}</button>`).join('')}</div><div id="pl-o-content"></div><details class="official-method"><summary>Import scope & sources</summary><p>Selected facts from the official Premier League record and corroborating official club sources, reviewed 17–18 October 2026. Each row links its source; public names and match participation have separate evidence. This is a local pinned import, with no live refresh or AI answers.</p><ul>${r.limits.map(l=>`<li>${esc(l)}</li>`).join('')}</ul><p>Source-use and external publication permissions remain separate from this local prototype.</p>${r.sources.map(s=>`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.publisher+' · '+s.id)} ↗</a> · observed ${esc(s.observedOn)}</p>`).join('')}</details></section>`;show(section);}
 panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!active||!b)return;if(b.id==='pl-o-explore')options.onExplore?.();else if(b.id==='pl-o-return')options.onReturn?.();else if(b.id.startsWith('pl-o-'))show(b.id.slice(5));});
 return {activate(){active=true;render();},deactivate(){active=false;},stop(){},focusHeading(){node('return').focus({preventScroll:true});}};
}
root.PLOfficialView={mount};
})(window);
